<?php
declare(strict_types=1);if(PHP_SAPI!=='cli'){http_response_code(404);exit;}$_SERVER['REQUEST_METHOD']='CLI';require_once __DIR__.'/../config/db.php';$c=db();$failed=false;$checks=['amount ranges'=>"SELECT COUNT(*) n FROM erp_employer_declaration_lines WHERE gross_amount<0 OR withheld_amount<0 OR withheld_amount>gross_amount",'tenant ownership'=>"SELECT COUNT(*) n FROM erp_employer_declaration_lines l JOIN erp_employer_declarations d ON d.id=l.declaration_id WHERE l.user_id<>d.user_id",'supplier source reconciliation'=>"SELECT COUNT(*) n FROM erp_employer_declaration_lines l JOIN erp_supplier_payments p ON p.id=l.source_supplier_payment_id JOIN erp_supplier_invoices si ON si.id=p.supplier_invoice_id WHERE l.category<>'SUPPLIER' OR l.user_id<>p.user_id OR p.voided_at IS NOT NULL OR ABS(l.gross_amount-COALESCE(p.amount_tnd,p.amount*si.exchange_rate))>0.001 OR YEAR(p.payment_date)<>(SELECT declaration_year FROM erp_employer_declarations WHERE id=l.declaration_id)"];
foreach($checks as $label=>$sql){$n=(int)$c->query($sql)->fetch_assoc()['n'];if($n){$failed=true;fwrite(STDERR,"FAIL $label: $n mismatch(es)\n");}else echo "PASS $label reconciles\n";}exit($failed?1:0);
